use std::process::Command; use super::{file_entry::{parse_ls_line, FileEntry}, safety::shell_quote_path};
pub fn list_remote(host:&str, path:&str)->anyhow::Result<Vec<FileEntry>>{ let cmd=format!("LC_ALL=C ls -la -- {}", shell_quote_path(path)); let out=Command::new("ssh").arg(host).arg(cmd).output()?; let text=String::from_utf8_lossy(&out.stdout); Ok(text.lines().skip(1).filter_map(parse_ls_line).filter(|e| e.name != "." && e.name != "..").collect()) }
pub fn preview_remote(host:&str, path:&str, max_bytes:u64)->anyhow::Result<String>{ let cmd=format!("test $(wc -c < {}) -le {} && sed -n '1,200p' {} || printf 'Preview skipped: file too large'", shell_quote_path(path), max_bytes, shell_quote_path(path)); let out=Command::new("ssh").arg(host).arg(cmd).output()?; Ok(String::from_utf8_lossy(&out.stdout).to_string()) }
